do $$ begin if not exists (select 1 from pg_roles where rolname='avuhz_command_service') then create role avuhz_command_service nologin nobypassrls nosuperuser nocreatedb nocreaterole noinherit; end if; end $$; grant usage on schema public to avuhz_command_service; alter table public.avuhz_diagnostic_agreement_authorities enable row level security; alter table public.avuhz_diagnostic_payment_verifications enable row level security; alter table public.avuhz_assessment_access_proposals enable row level security; alter table public.avuhz_assessment_access_grants enable row level security; revoke all on table public.avuhz_acquisition_handoffs,public.avuhz_engagements,public.avuhz_diagnostic_scopes,public.avuhz_human_approvals,public.avuhz_idempotency_records,public.avuhz_lifecycle_events,public.avuhz_outbox_deliveries,public.avuhz_diagnostic_agreement_authorities,public.avuhz_diagnostic_payment_verifications,public.avuhz_assessment_access_proposals,public.avuhz_assessment_access_grants from anon,authenticated,public; grant select on table public.avuhz_acquisition_handoffs,public.avuhz_engagements,public.avuhz_diagnostic_scopes,public.avuhz_human_approvals,public.avuhz_idempotency_records,public.avuhz_lifecycle_events,public.avuhz_outbox_deliveries,public.avuhz_diagnostic_agreement_authorities,public.avuhz_diagnostic_payment_verifications,public.avuhz_assessment_access_proposals,public.avuhz_assessment_access_grants to avuhz_command_service; grant insert on table public.avuhz_engagements,public.avuhz_diagnostic_scopes,public.avuhz_human_approvals,public.avuhz_idempotency_records,public.avuhz_lifecycle_events,public.avuhz_outbox_deliveries,public.avuhz_diagnostic_agreement_authorities,public.avuhz_diagnostic_payment_verifications,public.avuhz_assessment_access_proposals,public.avuhz_assessment_access_grants to avuhz_command_service; grant update (accepted_at) on public.avuhz_acquisition_handoffs to avuhz_command_service; grant update (status,effective_at,canonical_scope_digest,record_version) on public.avuhz_diagnostic_scopes to avuhz_command_service; grant update (verification_status,invalidated_at,record_version) on public.avuhz_diagnostic_payment_verifications to avuhz_command_service; grant update (status,consumed_at,record_version) on public.avuhz_assessment_access_proposals to avuhz_command_service; grant update (status,verified_at,active_from,expires_at,revoked_at,closed_at,closure_reason,record_version) on public.avuhz_assessment_access_grants to avuhz_command_service; grant update (processing_status,result_reference,completed_at,record_version) on public.avuhz_idempotency_records to avuhz_command_service; do $$ declare t text; begin foreach t in array array['avuhz_acquisition_handoffs','avuhz_engagements','avuhz_diagnostic_scopes','avuhz_human_approvals','avuhz_idempotency_records','avuhz_lifecycle_events','avuhz_outbox_deliveries','avuhz_diagnostic_agreement_authorities','avuhz_diagnostic_payment_verifications','avuhz_assessment_access_proposals','avuhz_assessment_access_grants'] loop execute format('create policy avuhz_command_service_tenant_isolation on public.%I for all to avuhz_command_service using (tenant_id = nullif(current_setting(''avuhz.tenant_id'',true),'''')::uuid) with check (tenant_id = nullif(current_setting(''avuhz.tenant_id'',true),'''')::uuid)',t); end loop; end $$;
